export function getAppsForLevel(
  level: AppDefinition['level'],
  enabledApps: string[],
  featureFlags: string[],
): AppDefinition[] {
  return APP_REGISTRY.filter((app) => {
    if (app.level !== level) return false
    if (app.featureFlag && !featureFlags.includes(app.featureFlag)) return false
    return enabledApps.includes(app.id)
  })
}
